const b=$json.body || $json;
const requestId=String(b.request_id || ('wf127-'+Date.now()));
const dealId=b.deal_id || null, leadId=b.lead_id || null, propertyId=b.property_id || null;
const agreementType=String(b.agreement_type || '').toLowerCase();
const exitStrategy=String(b.exit_strategy || b.disposition_strategy || '').toLowerCase();
const buyerId=b.buyer_id || b.assignee_id || null;
const buyerStatus=String(b.buyer_status || b.assignee_status || '').toLowerCase();
const pofStatus=String(b.proof_of_funds_status || b.funding_status || '').toLowerCase();
const fundingStatus=String(b.funding_readiness || b.funding_status || '').toLowerCase();
const assignmentStatus=String(b.assignment_status || '').toLowerCase();
const novationStatus=String(b.novation_status || '').toLowerCase();
const doubleCloseFundingStatus=String(b.double_close_funding_status || '').toLowerCase();
const dnc=Boolean(b.dnc), missing=[];
if(!dealId) missing.push('deal_id'); if(!leadId) missing.push('lead_id'); if(!propertyId) missing.push('property_id'); if(!agreementType) missing.push('agreement_type'); if(!exitStrategy) missing.push('exit_strategy');
const blockers=[];
const bad=['failed','issue','blocked','rejected','expired'];
for(const [label,value] of [['buyer_or_assignee',buyerStatus],['proof_of_funds',pofStatus],['funding',fundingStatus],['assignment',assignmentStatus],['novation',novationStatus],['double_close_funding',doubleCloseFundingStatus]]) if(value && bad.includes(value)) blockers.push(label);
const buyerRequired=['assignment','novation','double_close'].includes(exitStrategy) || ['assignment','novation','double_close'].includes(agreementType);
const fundingRequired=['double_close','double close','double-close'].includes(exitStrategy) || ['double_close','double close','double-close'].includes(agreementType);
if(buyerRequired && !buyerId) blockers.push('buyer_or_assignee_identity');
if(buyerRequired && !['ready','selected','confirmed'].includes(buyerStatus)) blockers.push('buyer_or_assignee_not_ready');
if(buyerRequired && !['verified','ready','confirmed','complete'].includes(pofStatus)) blockers.push('proof_of_funds_not_verified');
if(fundingRequired && !['ready','verified','confirmed','funded','complete'].includes(fundingStatus)) blockers.push('funding_not_ready');
if(exitStrategy==='assignment' && !['ready','confirmed','complete'].includes(assignmentStatus)) blockers.push('assignment_not_ready');
if(exitStrategy==='novation' && !['ready','confirmed','complete'].includes(novationStatus)) blockers.push('novation_not_ready');
if(fundingRequired && !['ready','verified','confirmed','funded','complete'].includes(doubleCloseFundingStatus)) blockers.push('double_close_funding_not_confirmed');
let status='blocked',nextState='human_review',route='human_review',reason='Buyer, assignee, or funding readiness requires review';
if(dnc){status='suppressed';nextState='disposition_readiness';route='none';reason='DNC suppresses communication only; disposition readiness is retained';}
else if(missing.length){status='blocked';nextState='missing_disposition_inputs';reason='Required disposition identity or exit strategy is missing';}
else if([...new Set(blockers)].length){status='blocked';nextState='disposition_blocked';reason='One or more buyer, funding, or exit-strategy conditions are unresolved';}
else{status='ready';nextState='closing_coordination';route='wf-126-closing-coordination-critical-date-controller';reason='Buyer/assignee and funding readiness satisfy the selected exit strategy';}
const id='buyer-funding-readiness:'+dealId+':'+requestId+':v1';
const uniqueBlockers=[...new Set(blockers)];
return [{json:{workflow:'WF-127',workflow_version:'1.0',request_id:requestId,buyer_funding_readiness_id:id,lead_id:leadId,property_id:propertyId,deal_id:dealId,agreement_type:agreementType,exit_strategy:exitStrategy,buyer_id:buyerId,buyer_status:buyerStatus,proof_of_funds_status:pofStatus,funding_status:fundingStatus,assignment_status:assignmentStatus,novation_status:novationStatus,double_close_funding_status:doubleCloseFundingStatus,buyer_required:buyerRequired,funding_required:fundingRequired,status,next_state:nextState,route,reason,blockers:uniqueBlockers,requirements:['selected buyer or assignee when required','buyer/assignee readiness confirmation','proof-of-funds or funding evidence when required','assignment/novation readiness when selected','double-close funding confirmation when selected'],guardrails:{buyer_required_for_disposition_exit:true,proof_of_funds_required_when_exit_requires_buyer:true,double_close_requires_funding_confirmation:true,no_invented_buyer_or_funding_evidence:true,unresolved_disposition_blockers_prevent_ready:true,dnc_suppresses_communication_not_transaction_state:true},crm_activity:{activity_type:'buyer_funding_readiness',subject:'WF-127 buyer/assignee and funding readiness - '+status,lead_id:leadId,property_id:propertyId,deal_id:dealId,external_id:id,external_source:'wholesaling-os-disposition',metadata:{status,next_state,route,reason,exit_strategy,buyer_id:buyerId,buyer_status:buyerStatus,proof_of_funds_status:pofStatus,funding_status:fundingStatus,assignment_status:assignmentStatus,novation_status:novationStatus,double_close_funding_status:doubleCloseFundingStatus,blockers:uniqueBlockers}}}}];
